<template>
  <div>
    <div style="padding-top: 1%">
      <div>
        <h1>Journal</h1>
        <h6 style="color: lightgray">
          <span v-if="thisLayout === PARAMS.Layout.Manage.value">{{ PARAMS.Layout.Manage.text }}</span>
          <span v-if="thisLayout === PARAMS.Layout.Add.value">{{ PARAMS.Layout.Add.text }}</span>
          <span v-if="thisLayout === PARAMS.Layout.Edit.value">{{ PARAMS.Layout.Edit.text }}</span>
        </h6>
      </div>
      <br />
      <div>
        <!-- Manage UI -->
        <div v-if="thisLayout === PARAMS.Layout.Manage.value">
          <span>
            <loading :display="display" :code="loadingCode" />
          </span>
          <div v-if="display === false">
            <table class="table">
              <thead>
                <tr>
                  <th>ID</th>
                  <th>Date</th>
                  <th>Debit</th>
                  <th>Credit</th>
                  <th>Amount</th>
                  <th>Info (Item / Place / Who)</th>
                  <th>Account</th>
                  <th>Time Modify</th>
                  <th>Operate</th>
                </tr>
                <tr>
                  <th></th>
                  <th>
                    <div class="form-group">
                      <div class="block">
                        <el-date-picker
                          v-model="entity.timeDate"
                          type="datetime"
                          placeholder="請選擇日期及時間"
                          format="yyyy-MM-dd"
                          align="right"
                          style="height:25px"/>
                      </div>
                    </div>
                    <input type="text" class="form-control" placeholder="請輸入..."
                      v-model="entity.timeDate" @change="queryEntity(entity, PARAMS.Layout.Action.Filter.symbol)" >
                  </th>
                  <th>
                    <select class="custom-select"
                      v-model="entity.debit" @change="queryEntity(entity, PARAMS.Layout.Action.Filter.symbol)">
                      <option v-for="(option, index) in subjectList" :key="index" :value="option.id">{{ option.name }}</option>
                    </select>
                  </th>
                  <th>
                    <select class="custom-select"
                      v-model="entity.credit" @change="queryEntity(entity, PARAMS.Layout.Action.Filter.symbol)">
                      <option v-for="(option, index) in subjectList" :key="index" :value="option.id">{{ option.name }}</option>
                    </select>
                  </th>
                  <th></th>
                  <th>
                    <div class="container row">
                      <div class="col-sm">
                        <input type="text" class="form-control" placeholder="請輸入項目..."
                          v-model="entity.item" @change="queryEntity(entity, PARAMS.Layout.Action.Filter.symbol)" >
                      </div>
                      <div class="col-sm">
                        <input type="text" class="form-control" placeholder="請輸入地點..."
                          v-model="entity.place" @change="queryEntity(entity, PARAMS.Layout.Action.Filter.symbol)" >
                      </div>
                      <div class="col-sm">
                        <input type="text" class="form-control" placeholder="誰..."
                          v-model="entity.who" @change="queryEntity(entity, PARAMS.Layout.Action.Filter.symbol)" >
                      </div>
                    </div>
                  </th>
                  <th></th>
                  <th></th>
                  <th>
                    <button type="button" class="btn btn-primary" @click="toLayout(PARAMS.Layout.Add.symbol)">Add</button>
                  </th>
                </tr>
              </thead>
              <tbody>
                <tr v-for="(bean, index) in entityList" :key="index">
                  <td>{{ bean.id }}</td>
                  <td>{{ toFormatDateTime(bean.timeDate, 'YYYY-MM-DD') }}</td>
                  <td>{{ getSubjectText(bean.debit) }}</td>
                  <td>{{ getSubjectText(bean.credit) }}</td>
                  <td>{{ bean.amount }}</td>
                  <td>{{ bean.item }}<br/>{{ bean.place }}<br />{{ bean.who }}</td>
                  <td>{{ getAccountText(bean.aId) }}</td>
                  <td>{{ toFormatDateTime(bean.timeModify) }}</td>
                  <td>
                    <button type="button" class="btn btn-outline-primary btn-circle" title="Edit"
                      @click="toLayout(PARAMS.Layout.Edit.symbol, bean)"><i class="material-icons">create</i></button>

                    <button type="button" class="btn btn-outline-danger btn-circle" title="Remove"
                      @click="deleteEntity(bean.id)"><i class="material-icons">delete</i></button>
                  </td>
                </tr>
              </tbody>
            </table>
          </div>
        </div>

        <!-- Add/Edit UI -->
        <div v-if="thisLayout !== PARAMS.Layout.Manage.value">
          <form class="was-validated">

            <!-- timeDate: datetimepicker -->
            <div v-if="thisLayout === PARAMS.Layout.Add.value">
              <label for="timeDate">Date</label>
              <input v-model="entity.timeDate" type="text" class="form-control is-invalid" id="timeDate"
                placeholder="timeDate" required>
              <div v-if="!validate.account" class="invalid-feedback">不可空白</div>
            </div>
            <div v-if="thisLayout === PARAMS.Layout.Edit.value">
              <label>Account</label>
              <input v-model="entity.account" type="text" class="form-control" placeholder="timeDate" readonly>
              <br />
            </div>

            <!-- debit -->
            <div>
              <label for="debit">Debit</label>
              <div class="form-group">
                <select class="custom-select" id="debit" v-model="entity.debit" required>
                  <option v-for="(subject, index) in subjectList" :key="index" :value="subject.id">{{ subject.name }}</option>
                </select>
                <div v-if="!validate.debit" class="invalid-feedback">請選擇借項科目</div>
              </div>
            </div>

            <!-- credit -->
            <div>
              <label for="credit">Credit</label>
              <div class="form-group">
                <select class="custom-select" id="credit" v-model="entity.credit" required>
                  <option v-for="(subject, index) in subjectList" :key="index" :value="subject.id">{{ subject.name }}</option>
                </select>
                <div v-if="!validate.credit" class="invalid-feedback">請選擇貸項科目</div>
              </div>
            </div>

            <!-- Amount -->
            <div>
              <label for="amount">Amount</label>
              <input v-model="entity.amount" type="number" class="form-control is-invalid" id="amount" placeholder="Amount" required>
              <div v-if="!validate.amount" class="invalid-feedback">不可空白</div>
            </div>
            <br />

            <!-- Item -->
            <div>
              <label for="item">Item</label>
              <input v-model="entity.item" type="number" class="form-control is-invalid" id="item" placeholder="Item" required>
              <div v-if="!validate.item" class="invalid-feedback">不可空白</div>
            </div>
            <br />

            <!-- Account -->
            <div>
              <label for="aId">Account</label>
              <div class="form-group">
                <select class="custom-select" id="aId" v-model="entity.aId" required>
                  <option v-for="(account, index) in accountList" :key="index" :value="account.id">{{ account.name }}</option>
                </select>
                <div v-if="!validate.aId" class="invalid-feedback">請選擇帳號</div>
              </div>
            </div>

          </form>
          <button type="button" class="btn btn-outline-dark" @click="toLayout(PARAMS.Layout.Action.Cancel.symbol)">Cancel</button>
          <button v-if="thisLayout === PARAMS.Layout.Add.value"
                  type="button" class="btn btn-outline-primary" @click="createEntity(entity)">Finish</button>
          <button v-if="thisLayout === PARAMS.Layout.Edit.value"
                  type="button" class="btn btn-outline-primary" @click="updateEntity(entity)">Update</button>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import loading from './Loading.vue'

export default {
  name: 'Journal',
  components: {
    'loading': loading
  },
  data () {
    return {
      API: {
        entityName: 'journal',
        query: {
          method: 'post',
          url: '/onAccountX/srv/journal'
        },
        create: {
          method: 'put',
          url: '/onAccountX/srv/journal'
        },
        update: {
          method: 'put',
          url: '/onAccountX/srv/journal/' // +id
        },
        delete: {
          method: 'delete',
          url: '/onAccountX/srv/journal/' // +id
        },
        querySubjectName: {
          method: 'get',
          url: '/onAccountX/srv/subject/list/name' // only id & code & name
        },
        queryAccountName: {
          method: 'get',
          url: '/onAccountX/srv/account/list/account' // only id & account
        }
        // enable: {
        //   method: 'put',
        //   url: '/onAccountX/srv/account/enable/' // +id
        // }
      },
      PARAMS: {
        Layout: {
          Manage: { symbol: 'manage', value: 0, text: '日記帳維護' },
          Add: { symbol: 'add', value: 1, text: '日記帳新增' },
          Edit: { symbol: 'edit', value: 2, text: '日記帳編輯' },
          Action: {
            Filter: { symbol: 'filter', value: 8, text: 'Filter' },
            Cancel: { symbol: 'cancel', value: 9, text: 'Cancel' }
          }
        }
        // Status: {
        //   default: { value: null, text: '請選擇...' },
        //   disable: { value: 0, text: '停用' },
        //   enable: { value: 1, text: '啟用中' },
        //   lock: { value: 4, text: '已鎖定' }
        // }
      },
      entity: {
        // Journal Object
        id: -1,
        timeDate: -1,
        debit: null, // ui 顯示 "請選擇..."
        credit: null,
        amount: -1,
        item: '',
        place: '',
        who: '',
        aId: null,
        timeModify: -1
      },

      // validate option
      validate: {
        // empty
        timeDate: false,
        debit: false,
        credit: false,
        amount: false,
        item: false,
        aId: false
      },
      validateFinal: false, // 檢查結果

      entityList: [],
      accountList: [],
      subjectList: [{
        id: null, // ui 顯示 "請選擇..."
        code: null,
        name: '請選擇...'
      }],

      // layout
      thisLayout: 0,

      // loading
      display: true,
      loadingCode: 0
    }
  },
  mounted () {
    this.queryEntity()
    this.querySubjectName()
    this.queryAccountName()
  },
  updated () {
    // var v = this.validate
    // var e = this.entity
    // // [add]
    // if (this.thisLayout === this.PARAMS.Layout.Add.value) {
    //   v.account = e.account !== ''
    //   // v.sameName 由 validateAccount() 處理
    //   v.password = (e.password !== null) && (e.password !== '')
    //   v.passwordAgain = (e.passwordAgain !== null) && (e.passwordAgain !== '')
    //   v.correctPassword = v.password && v.passwordAgain && (e.password === e.passwordAgain)
    //   v.oldPasswordAgain = true
    // }
    // // [edit]
    // if (this.thisLayout === this.PARAMS.Layout.Edit.value) {
    //   v.account = true
    //   v.sameName = true
    //   // 是否變更密碼
    //   if (this.changePassword) {
    //     // 變更密碼 -> 新密碼
    //     v.password = (e.password !== null) && (e.password !== '')
    //     v.passwordAgain = (e.passwordAgain !== null) && (e.passwordAgain !== '')
    //     v.correctPassword = v.password && v.passwordAgain && (e.password === e.passwordAgain)
    //   } else {
    //     // 不改密碼
    //     v.password = true
    //     v.passwordAgain = true
    //     v.correctPassword = true
    //   }
    //   v.oldPasswordAgain = (e.oldPasswordAgain !== null) && (e.oldPasswordAgain !== '')
    // }
    // v.memberId = (e.memberId !== null) && (e.status !== -1)
    // v.status = (e.status !== null) && (e.status !== -1)
  },
  methods: {
    /* Initial */

    // [初始化資料] 每次切換頁面
    initData (self, bean) {
      switch (self.thisLayout) {
        // 編輯頁面 -> 需回填資料
        case self.PARAMS.Layout.Edit.value:
          if (bean) {
            self.entity = {
              // Journal Object
              id: bean.id,
              debit: bean.debit,
              credit: bean.credit,
              amount: bean.amount,
              item: bean.item,
              place: bean.palce,
              who: bean.who,
              aId: bean.aId,
              timeModify: -1 // 由 API 處理
            }
          } else {
            console.log(`>>> Error: 'bean' is not defined.`)
          }
          break
        // 其餘頁面
        default:
          self.entity = {
            // Journal Object
            id: -1,
            timeDate: null,
            debit: null,
            credit: null,
            amount: -1,
            item: '',
            place: '',
            who: '',
            aId: null,
            timeModify: -1 // 不處理
          }
          break
      }
      self.validate = {
        // empty
        timeDate: false,
        debit: false,
        credit: false,
        amount: false,
        item: false,
        aId: false
      }
      self.validateFinal = false
    },

    /* Bean */

    // 查詢欄位 -> filter 資料用
    queryBean (bean) {
      var apiBean = {
        timeDate: -1,
        debit: null,
        credit: null,
        item: '',
        place: '',
        who: ''
      }
      if (bean) {
        apiBean = {
          timeDate: (bean.timeDate !== -1) ? bean.timeDate : null,
          debit: (bean.debit !== null) ? bean.debit : null,
          credit: (bean.credit !== null) ? bean.credit : null,
          item: (bean.item !== '') ? bean.item : null,
          place: (bean.place !== '') ? bean.place : null,
          who: (bean.who !== '') ? bean.who : null
        }
      }
      return apiBean
    },
    // 新增修改資料 -> create, update 資料用
    saveBean (bean) {
      return {
        id: bean.id,
        timeDate: (bean.timeDate === -1) ? null : bean.timeDate,
        debit: bean.debit,
        credit: bean.credit,
        amount: bean.amount,
        item: bean.item,
        place: bean.place,
        who: bean.who,
        aId: bean.aId,
        timeModify: bean.timeModify
      }
    },
    // 打包 API 用 Entity
    pkgApiEntity (apiBean) {
      return {
        journal: apiBean
      }
    },

    /* API */

    queryEntity (bean, symbol) {
      var self = this
      var apiBean = this.queryBean(bean)
      axios({
        method: self.API.query.method,
        url: self.API.query.url,
        headers: {
          'Content-Type': 'application/json',
          'mac': 'helloJWT'
        },
        data: self.pkgApiEntity(apiBean)
      }).then(function (response) {
        console.log('queryEntity: ', response)
        if (response) {
          self.entityList = response.data.data
        }
        self.display = false
        self.toLayout(self.PARAMS.Layout.Manage.symbol, null, symbol)
      }).catch(function (error) {
        console.log('>>> Error: query ' + self.API.entityName + ' failed: ', error)
      })
    },
    createEntity (bean) {
      var self = this
      var v = this.validate
      var apiBean = self.saveBean(bean)

      // all check
      var final = true
      for (var item in v) {
        if (!v[item]) {
          final = false
        }
      }
      self.validateFinal = final

      // execute
      if (self.validateFinal) {
        axios({
          method: self.API.create.method,
          url: self.API.create.url,
          headers: {
            'Content-Type': 'application/json',
            'mac': 'helloJWT'
          },
          data: self.pkgApiEntity(apiBean)
        }).then(function (response) {
          if (response) {
            self.queryEntity()
            alert('新增完成')
          }
        }).catch(function (error) {
          console.log('>>> Error: Add failed: ', error)
        })
      } else {
        alert('請檢查是否有欄位未填寫')
      }
    },
    updateEntity (bean) {
      var self = this
      var v = this.validate
      var apiBean = this.saveBean(bean)

      /* validate */
      // account -> v.sameName
      v.sameName = true
      // all check
      var final = true
      for (var item in v) {
        if (!v[item]) {
          final = false
        }
        // console.log(item + ':' + v[item])
      }
      self.validateFinal = final

      // execute
      if (self.validateFinal) {
        axios({
          method: self.API.update.method,
          url: self.API.update.url + apiBean.id,
          headers: {
            'Content-Type': 'application/json',
            'mac': 'helloJWT'
          },
          data: self.pkgApiEntity(apiBean)
        }).then(function (response) {
          if (response) {
            if (response.data.statusCode === 499) {
              alert('驗證身分失敗, 請重新輸入舊密碼')
            } else {
              self.queryEntity()
              alert('更新完成')
            }
          }
        }).catch(function (error) {
          console.log('>>> Error: Edit ' + self.API.entityName + ' failed: ', error)
        })
      } else {
        alert('請檢查是否有欄位未填寫')
      }
    },
    deleteEntity (id) {
      var self = this
      if (confirm('確定要刪除 ' + id + ' ?')) {
        axios({
          method: self.API.delete.method,
          url: self.API.delete.url + id,
          headers: {
            'Content-Type': 'application/json',
            'mac': 'helloJWT'
          }
        }).then(function (response) {
          if (response) {
            self.queryEntity()
            alert('刪除完成')
          }
        }).catch(function (error) {
          console.log('>>> Error: Delete ' + self.API.entityName + ' failed: ', error)
        })
      }
    },

    /* API - other */

    // 取得 subject list -> only id & code & name
    querySubjectName () {
      var self = this
      axios({
        method: this.API.querySubjectName.method,
        url: this.API.querySubjectName.url,
        headers: {
          'Content-Type': 'application/json',
          'mac': 'helloJWT'
        },
        data: {}
      }).then(function (response) {
        console.log(self.subjectList)
        console.log('response: ', response)
        if (response) {
          self.subjectList = self.subjectList.concat(response.data.data)
          console.log('self.subjectList: ', self.subjectList)
        }
        self.display = false
      }).catch(function (error) {
        console.log('>>> Error: query ' + self.API.entityName + ' failed: ', error)
      })
      console.log(self.subjectList)
    },
    // 取得 account list -> only id & account
    queryAccountName () {
      var self = this
      axios({
        method: self.API.queryAccountName.method,
        url: self.API.queryAccountName.url,
        headers: {
          'Content-Type': 'application/json',
          'mac': 'helloJWT'
        },
        data: {}
      }).then(function (response) {
        if (response) {
          self.accountList = response.data.data
          // console.log(response.data.data)
        }
      }).catch(function (error) {
        console.log('>>> Error: validate ' + self.API.entityName + ' failed: ', error)
      })
      // console.log(self.accountList)
    },

    /* Util - custom */

    // 取得 subject text by id
    getSubjectText (id) {
      var self = this
      var str = 'Error'
      self.subjectList.forEach(s => {
        if (id === s.id) {
          str = s.name
        }
      })
      return str
    },
    // 取得 account text by id
    getAccountText (id) {
      var self = this
      var str = 'Error'
      self.accountList.forEach(a => {
        if (id === a.id) {
          str = a.account
        }
      })
      return str
    },
    // Layout 切換
    toLayout (symbol, bean, actionSymbol) {
      var self = this
      var layout = self.PARAMS.Layout
      var fromLayout = self.thisLayout
      switch (symbol) {
        case layout.Manage.symbol:
          self.thisLayout = layout.Manage.value
          break
        case layout.Action.Cancel.symbol:
          var info = (fromLayout === layout.Add.value)
            ? ('確定取消 ' + layout.Add.text)
            : ('確定取消 ' + layout.Edit.text)
          if (confirm(info + ' ?')) {
            self.thisLayout = layout.Manage.value
          }
          break
        case layout.Edit.symbol:
          self.thisLayout = layout.Edit.value
          break
        case layout.Add.symbol:
          self.thisLayout = layout.Add.value
          break
      }
      // 編輯時需回填資料
      if (self.thisLayout === layout.Edit.value) {
        if (bean) {
          self.initData(self, bean)
        } else {
          console.log(`>>> Error: 'bean' is not defined.`)
        }
      } else {
        if (actionSymbol === self.PARAMS.Layout.Action.Filter.symbol) {
          // filter 存在 -> 不初始化資料
        } else {
          self.initData(self)
        }
      }
    },

    /* Util */

    // [時間格式] 取得格式化(YYY-MM-DD HH:mm)後的日期時間字串
    toFormatDateTime (timestamp, formatStr) {
      /* 1: timestamp 傳入是日期(string)   '2019-7-12 9:17', 則回傳 '2019-07-12 09:17'
       * 2: timestamp 傳入是時間戳(number) 1562894220000, 則回傳 '2019-07-12 09:17'
       * 3: timestamp 傳入是空的(null)     (null), 則回傳 'null'
       * p.s. formatStr 為 Y(年) M(月) D(日) H(時) m(分) s(秒) 組成 */
      // 變成 Date 物件，再拿時間戳(getTime() 回傳的是 number 型態)
      var fmtStr = (formatStr === undefined || formatStr === null) ? 'YYYY-MM-DD HH:mm' : formatStr
      if (timestamp) {
        switch (typeof timestamp) {
          case 'number':
            return moment(timestamp).format(fmtStr)
          case 'string':
            timestamp = new Date(timestamp).getTime()
            return moment(timestamp).format(fmtStr)
          default:
            console.log('Error: 時間轉換型態必須是 Number 或 String')
        }
      }
      return null
    }
  }
}
</script>

<!-- Add "scoped" attribute to limit CSS to this component only -->
<style scoped>
h1, h2, h6, span {
  font-weight: normal;
  text-align: center;
}
ul {
  list-style-type: none;
  padding: 0;
}
li {
  display: inline-block;
  margin: 0 10px;
}
a {
  color: #42b983;
}
.btn-circle {
  width: 30px;
  height: 30px;
  padding: 6px 0px;
  border-radius: 15px;
  text-align: center;
  font-size: 12px;
  line-height: 1.42857;
}
</style>



